PAGE = dict(
    slug='cloud3',
    title='Pane::cloud3',
    signature='Trace& Pane::cloud3(Series x, Series y, Series z)\nTrace& Pane::cloud3(Series x, Series y, Series z, Series size)\nTrace& Pane::cloud3(Series x, Series y, Series z, Series size, Series color)',
    intro='Adds a **cloud in three dimensions**: a marker at each point `(x[i], y[i], z[i])`, with nothing joining them. It is the three-dimensional [`cloud`](cloud.md), a scatter plot in space, and with the optional series it carries a size and a colour for each marker.\n\n| Call | Adds |\n|---|---|\n| `cloud3(x, y, z)` | Markers of one size and colour. |\n| `cloud3(x, y, z, size)` | A size for each marker. |\n| `cloud3(x, y, z, size, color)` | And a colour for each, from the palette over the range of `color`. |\n\nAs for `cloud`, there is no call with a colour and no size. All series have the same length, or length 1.',
    parameters='**x**, **y**, **z** (`Series`-convertible)\n    The positions.\n\n**size**, **color** (`Series`-convertible, optional)\n    Size and colour value of each marker, or one for all.',
    returns='`Trace&`\n    The new trace.',
    examples=[
        dict(id='plain', text='A marker at each point of the helix.',
             code='auto fig = studio("cloud3_plain");\nauto& pane = fig.pane3("p");\nstd::vector<double> hx, hy, hz;\nfor (int i = 0; i <= 40; ++i) {\n  const double t = 0.25 * i;\n  hx.push_back(std::cos(t));\n  hy.push_back(std::sin(t));\n  hz.push_back(0.1 * t);\n}\npane.cloud3(hx, hy, hz);\nfig.save_svg("figure.svg");'),
        dict(id='size', text='A fourth series gives each marker its own size: here they grow along the helix.',
             code='auto fig = studio("cloud3_size");\nauto& pane = fig.pane3("p");\nstd::vector<double> hx, hy, hz;\nfor (int i = 0; i <= 40; ++i) {\n  const double t = 0.25 * i;\n  hx.push_back(std::cos(t));\n  hy.push_back(std::sin(t));\n  hz.push_back(0.1 * t);\n}\nstd::vector<double> size;\nfor (std::size_t i = 0; i < hx.size(); ++i) size.push_back(10.0 + 2.0 * i);\npane.cloud3(hx, hy, hz, size);\nfig.save_svg("figure.svg");'),
        dict(id='color', text='A fifth series colours the markers through the palette, with the guide to say what the colours mean. A single size keeps the markers equal.',
             code='auto fig = studio("cloud3_color");\nauto& pane = fig.pane3("p");\nstd::vector<double> hx, hy, hz;\nfor (int i = 0; i <= 40; ++i) {\n  const double t = 0.25 * i;\n  hx.push_back(std::cos(t));\n  hy.push_back(std::sin(t));\n  hz.push_back(0.1 * t);\n}\npane.cloud3(hx, hy, hz, std::vector<double>{3}, hz);\npane.scale_guide(true);\nfig.save_svg("figure.svg");'),
        dict(id='scalar', text='A single size or colour is repeated for every point.',
             code='auto build = [&](double size) {\n  auto fig = studio("cloud3_scalar");\n  auto& pane = fig.pane3("p");\n  pane.cloud3(std::vector<double>{0, 1, 2}, std::vector<double>{0, 1, 0}, std::vector<double>{0, 1, 2}, std::vector<double>{size});\n  return fig.to_svg();\n};\nstd::cout << "size 50 != size 150: " << (build(50.0) != build(150.0)) << "\\n";\nauto fig = studio("cloud3_scalar_out");\nauto& pane = fig.pane3("p");\npane.cloud3(std::vector<double>{0, 1, 2}, std::vector<double>{0, 1, 0}, std::vector<double>{0, 1, 2}, std::vector<double>{150});\nfig.save_svg("figure.svg");'),
        dict(id='errors', text='Inputs that cannot be drawn are refused when the trace is added, and the message names the method and the problem. The pane keeps the traces it had.',
             code='auto report = [](const char* what, auto&& call) {\n  auto fig = studio("cloud3_errors");\n  auto& pane = fig.pane3("p");\n  try {\n    call(pane);\n    std::cout << what << ": accepted\\n";\n  } catch (const pluss::Error& e) {\n    std::cout << what << ": " << e.message() << "\\n";\n  }\n};\nreport("z differs", [](Pane& pane) { pane.cloud3(std::vector<double>{1, 2, 3}, std::vector<double>{1, 2, 3}, std::vector<double>{1, 2}); });\nreport("size differs", [](Pane& pane) { pane.cloud3(std::vector<double>{1, 2, 3}, std::vector<double>{1, 2, 3}, std::vector<double>{1, 2, 3}, std::vector<double>{1, 2}); });\nauto fig = studio("cloud3_errors_out");\nauto& pane = fig.pane3("p");\npane.path3(std::vector<double>{0, 1}, std::vector<double>{0, 1}, std::vector<double>{0, 1});\nfig.save_svg("figure.svg");'),
        dict(id='wrong_pane', text='`cloud3` needs a volumetric pane. On a planar pane it throws at once, naming the kind it needs, and nothing is added.',
             code='auto fig = studio("cloud3_wrong_pane");\nauto& pane = fig.pane2("p");\ntry {\n  pane.cloud3(std::vector<double>{0, 1}, std::vector<double>{0, 1}, std::vector<double>{0, 1});\n} catch (const pluss::Error& e) {\n  std::cout << e.message() << "\\n";\n}\nstd::cout << "traces: " << pane.trace_count() << "\\n";\nfig.save_svg("figure.svg");'),
    ],
    notes='- Returns the new [`Trace&`](../trace/label.md); the reference stays valid for the life of the pane, and the style calls of the trace ([`label`](../trace/label.md), [`stroke`](../trace/stroke.md), [`width`](../trace/width.md), ...) chain off it.\n- The data is copied into the trace when it is added, so changing the vector afterwards does not change the figure.\n',
    see=['[`Pane::cloud`](cloud.md): the planar form.', '[`Pane::path3`](path3.md): a line through points.', '[`Pane::scale_guide`](scale_guide.md): the key to the colours.'],
)
